import{_ as a,o as l,c as r,ah as d}from"./chunks/framework.DOp2Lr4v.js";const p="/projects/TonyPi-Pro/en/latest/assets/image3.CdGOKV2K.png",o="data:image/png;base64,",t="/projects/TonyPi-Pro/en/latest/assets/image1.PGu2rbCU.png",e="/projects/TonyPi-Pro/en/latest/assets/image2.B-CK2Jti.png",i="/projects/TonyPi-Pro/en/latest/assets/image3.DXc5Ea0f.png",h="/projects/TonyPi-Pro/en/latest/assets/image4.BREhNKQE.png",n="/projects/TonyPi-Pro/en/latest/assets/image5.828ABNbf.png",c="/projects/TonyPi-Pro/en/latest/assets/image6.CCpyoY4l.png",g="/projects/TonyPi-Pro/en/latest/assets/image7.vg7jSRNq.png",m="/projects/TonyPi-Pro/en/latest/assets/image8.ISBKc_n-.png",u="/projects/TonyPi-Pro/en/latest/assets/image9.KxhRVdEC.png",y="/projects/TonyPi-Pro/en/latest/assets/image10.BzBj5Y_k.png",b="/projects/TonyPi-Pro/en/latest/assets/image11.DWy5dnuz.png",k="/projects/TonyPi-Pro/en/latest/assets/image12.Sqzk-yzr.png",v="/projects/TonyPi-Pro/en/latest/assets/image13.UIjgmsrA.png",A=JSON.parse('{"title":"15 Group Control Course","description":"","frontmatter":{},"headers":[],"relativePath":"docs/15_Group Control Course.md","filePath":"docs/15_Group Control Course.md"}'),E={name:"docs/15_Group Control Course.md"};function f(w,s,x,_,P,C){return l(),r("div",null,[...s[0]||(s[0]=[d('<h1 id="_15-group-control-course" tabindex="-1">15 Group Control Course <a class="header-anchor" href="#_15-group-control-course" aria-label="Permalink to &quot;15 Group Control Course&quot;">​</a></h1><h2 id="_15-1-wireless-controller-control" tabindex="-1">15.1 Wireless Controller Control <a class="header-anchor" href="#_15-1-wireless-controller-control" aria-label="Permalink to &quot;15.1 Wireless Controller Control&quot;">​</a></h2><h3 id="_15-1-1-getting-ready" tabindex="-1">15.1.1 Getting Ready <a class="header-anchor" href="#_15-1-1-getting-ready" aria-label="Permalink to &quot;15.1.1 Getting Ready&quot;">​</a></h3><p>Step 1: Plug the controller receiver into one of USB ports of TonyPi.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>Note: The controller receiver must be inserted before the robot is turned on.</strong></p></div><p>Step 2: Prepare two AAA batteries. Take off the back cover of the handle and insert them into the battery slot. Please pay attention to the direction of the positive and negative poles.</p><img loading="lazy" height="365" width="977" class="common_img" src="'+p+'" style="width:500px;"><h3 id="_15-1-2-device-connection" tabindex="-1">15.1.2 Device Connection <a class="header-anchor" href="#_15-1-2-device-connection" aria-label="Permalink to &quot;15.1.2 Device Connection&quot;">​</a></h3><p>If you do not connect the robot within 30 seconds after turning on the handle switch, or if you do not operate the handle within 5 minutes after connecting it, the handle will enter</p><p>sleep mode. If you need to turn on the handle again, press the &quot;<strong>START</strong>&quot; button.</p><p>Step 1: Turn on the robot.</p><p>Step 2: Switch on the handle, and then the two LED lights (red and green) on handle will flash simultaneously.</p><p>Step 3: Wait for a few seconds, pair the handle with the robot. After pairing, the</p><p>green light will keep on.</p><h3 id="_15-1-3-mode-introduction" tabindex="-1">15.1.3 Mode Introduction <a class="header-anchor" href="#_15-1-3-mode-introduction" aria-label="Permalink to &quot;15.1.3 Mode Introduction&quot;">​</a></h3><p>The handle has two modes: single green light mode and green and red lights mode (The red and green lights will turn on simultaneously ).</p><p><strong>Single green light mode:</strong> all the buttons can be used.</p><p><strong>Red and green lights mode:</strong> the four buttons “<strong>↑</strong> 、<strong>↓</strong>、<strong>←</strong>、<strong>→</strong>” are locked and can not be used. The function of the remaining buttons is the same as that of the green and red lights mode.</p><p>Two modes switching method: press “<strong>MODE</strong>” button to switch the mode from the green light mode to another mode, and press the button again to switch to the green light mode.</p><h3 id="_15-1-4-button-instruction" tabindex="-1">15.1.4 Button Instruction <a class="header-anchor" href="#_15-1-4-button-instruction" aria-label="Permalink to &quot;15.1.4 Button Instruction&quot;">​</a></h3><p>The corresponding relation between the button and the action is as the following table:</p><table tabindex="0"><thead><tr><th style="text-align:center;">Button</th><th style="text-align:center;">Function</th></tr></thead><tbody><tr><td style="text-align:center;">START</td><td style="text-align:center;">the robot returns to the initial posture</td></tr><tr><td style="text-align:center;">L1</td><td style="text-align:center;">right tilt and lift the left foot</td></tr><tr><td style="text-align:center;">R1</td><td style="text-align:center;">left tilt and lift right foot</td></tr><tr><td style="text-align:center;">↑</td><td style="text-align:center;">move forward</td></tr><tr><td style="text-align:center;">↓</td><td style="text-align:center;">move backward</td></tr><tr><td style="text-align:center;">←</td><td style="text-align:center;">move to left</td></tr><tr><td style="text-align:center;">→</td><td style="text-align:center;">move to right</td></tr><tr><td style="text-align:center;">△</td><td style="text-align:center;">wave</td></tr><tr><td style="text-align:center;">×</td><td style="text-align:center;">bow</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="19" width="31" class="common_img" src="'+o+'" style="width:40px;"></td><td style="text-align:center;">twist waist</td></tr><tr><td style="text-align:center;">○</td><td style="text-align:center;">right-footed shot</td></tr><tr><td style="text-align:center;">Push up the left slider</td><td style="text-align:center;">move forward</td></tr><tr><td style="text-align:center;">Push down the left slider</td><td style="text-align:center;">move backward</td></tr><tr><td style="text-align:center;">Push the left slider to left</td><td style="text-align:center;">move to left</td></tr><tr><td style="text-align:center;">select+L1</td><td style="text-align:center;">Dance 1</td></tr><tr><td style="text-align:center;">select+L2</td><td style="text-align:center;">Dance 2</td></tr><tr><td style="text-align:center;">select+R1</td><td style="text-align:center;">Dance 3</td></tr><tr><td style="text-align:center;">select+R2</td><td style="text-align:center;">Dance 4</td></tr><tr><td style="text-align:center;">select+△</td><td style="text-align:center;">Dance 5</td></tr><tr><td style="text-align:center;">select+<img loading="lazy" height="19" width="31" class="common_img" src="'+o+'" style="width:40px;"></td><td style="text-align:center;">Dance 6</td></tr><tr><td style="text-align:center;">select+○</td><td style="text-align:center;">Dance 7</td></tr><tr><td style="text-align:center;">select+start</td><td style="text-align:center;">Activate athlete mode</td></tr></tbody></table><h2 id="_15-2-group-control" tabindex="-1">15.2 Group Control <a class="header-anchor" href="#_15-2-group-control" aria-label="Permalink to &quot;15.2 Group Control&quot;">​</a></h2><h3 id="_15-2-1-getting-started" tabindex="-1">15.2.1 Getting Started <a class="header-anchor" href="#_15-2-1-getting-started" aria-label="Permalink to &quot;15.2.1 Getting Started&quot;">​</a></h3><ol><li><p>Prepare at least two TonyPi Pro robots. In this lesson, two TonyPi Pro robots are used for demonstrating.</p></li><li><p>Set up the development environment. Refer to “<strong><a href="https://drive.google.com/drive/folders/1aEXEUxJD5vHFtTVFyGs2Dt8q5HPY-cGk?usp=sharing" target="_blank" rel="noreferrer">Remote Desktop Tool Installation and Connection \\ Remote Tool Installation and Connection</a></strong>” to download and install the VNC remote connection tool.</p></li></ol><h3 id="_15-2-2-introduction" tabindex="-1">15.2.2 Introduction <a class="header-anchor" href="#_15-2-2-introduction" aria-label="Permalink to &quot;15.2.2 Introduction&quot;">​</a></h3><p>By configuring the master and slave robots on the same network, the master can send action commands to the slave robots through the group control program, enabling control of the slave robots.</p><h3 id="_15-2-3-group-control-setup" tabindex="-1">15.2.3 Group Control Setup <a class="header-anchor" href="#_15-2-3-group-control-setup" aria-label="Permalink to &quot;15.2.3 Group Control Setup&quot;">​</a></h3><p>There are two ways to perform group control: LAN mode and master-slave mode.</p><ul><li><strong>LAN Mode</strong></li></ul><p><strong>1. Network Configuration</strong></p><p>First, connect all robots that need group control to the same local network using a Wi-Fi router with a strong signal.</p><ol><li><p>Open the command line terminal and navigate to the Wi-Fi configuration directory. Enter the following command and press <strong>Enter</strong>.</p><div class="language-py vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">py</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cd hiwonder</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">toolbox</span></span></code></pre></div></li></ol><img loading="lazy" height="83" width="734" class="common_img" src="'+t+'" style="width:500px;"><ol start="2"><li><p>Open the Wi-Fi configuration file using the vi editor by entering:</p><div class="language-py vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">py</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sudo vim wifi_conf.py</span></span></code></pre></div></li></ol><img loading="lazy" height="31" width="504" class="common_img" src="'+e+'" style="width:500px;"><ol start="3"><li>Press the <strong>i</strong> key to enter edit mode.</li></ol><img loading="lazy" height="622" width="749" class="common_img" src="'+i+'" style="width:500px;"><ol start="4"><li>Modify the value of HW_WIFI_MODE to 2, and change the values of WIFI_SSID and PASSWORD fields to match your Wi-Fi network name and password.</li></ol><img loading="lazy" height="41" width="714" class="common_img" src="'+h+'" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The password must be at least 8 characters long.</strong></p></div><ol start="5"><li><p>After modifying, press <strong>Esc</strong> to exit edit mode, then save and exit by entering:</p><div class="language-py vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">py</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:wq</span></span></code></pre></div></li></ol><img loading="lazy" height="284" width="741" class="common_img" src="'+n+'" style="width:500px;"><ol start="6"><li><p>Finally, reboot the device by entering the following command. <strong>Do not skip this step.</strong></p><div class="language-py vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">py</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sudo reboot</span></span></code></pre></div></li><li><p>Repeat the above steps for all robots, ensuring they are all configured on the same local network.</p></li></ol><p><strong>2. IP Address Configuration</strong></p><ol><li><p>On any TonyPi Pro, open the command line terminal and enter the following command to check the device’s IP address. Remember this IP address, as it will be used as the server IP for forwarding:</p><div class="language-py vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">py</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ifconfig</span></span></code></pre></div></li></ol><img loading="lazy" height="463" width="745" class="common_img" src="'+c+'" style="width:500px;"><ol start="2"><li><p>Insert the wireless controller&#39;s receiver into this TonyPi Pro, which will act as the master device.</p></li><li><p>Edit the local forwarding address in the wireless controller’s control program by entering:</p><div class="language-py vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">py</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">vim </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">~/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TonyPi</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Joystick.py</span></span></code></pre></div></li></ol><img loading="lazy" height="187" width="903" class="common_img" src="'+g+'" style="width:500px;"><ol start="4"><li><p>Next, remotely connect to the other robots that need to be controlled, and configure the client IP address by entering:</p><div class="language-py vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">py</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">vim </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">~/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TonyPi</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Extend</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">multi_control</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">multi_control_client.py</span></span></code></pre></div></li><li><p>Modify the relevant section to the server IP address you checked. After changing it, press <strong>Esc</strong> and enter :wq to save and exit.</p></li></ol><img loading="lazy" height="326" width="763" class="common_img" src="'+m+'" style="width:500px;"><ol start="6"><li><p>Finally, reboot the device by entering the following command. <strong>Do not skip this step.</strong></p><div class="language-py vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">py</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sudo reboot</span></span></code></pre></div></li><li><p>Repeat the above IP configuration steps for all other robots.</p></li></ol><p><strong>3. Group Control</strong></p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>Note:</strong> When using group control, first power on the robot with the wireless controller receiver, then start the other robots.</p></div><ol><li><p>Place all robots on a flat, open surface, keeping a reasonable distance between each robot.</p></li><li><p>During group control, only single commands can be sent. To perform actions such as continuously moving forward, <strong>press the controller buttons multiple times</strong> instead of holding the stick.</p></li></ol><ul><li><strong>Master-Slave Mode</strong></li></ul><p><strong>1. Master Robot Configuration</strong></p><ol><li>First, power on one robot to serve as the master and establish a remote desktop connection. In this example, the robot with the hotspot named <strong>HW-F199CEEE</strong> is used.</li></ol><img loading="lazy" height="285" width="358" class="common_img" src="'+u+'" style="width:500px;" alt="QQ图片20211213152528"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>Remember the master robot’s hotspot name, as it will be used in the following steps.</strong></p></div><ol start="2"><li><p>Open the command line terminal and navigate to the Wi-Fi configuration directory. Enter the following command and press <strong>Enter</strong>.</p><div class="language-py vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">py</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cd hiwonder</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">toolbox</span></span></code></pre></div></li></ol><img loading="lazy" height="83" width="734" class="common_img" src="'+t+'" style="width:500px;"><ol start="3"><li><p>Open the Wi-Fi configuration file using the vi editor by entering:</p><div class="language-py vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">py</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sudo vim wifi_conf.py</span></span></code></pre></div></li></ol><img loading="lazy" height="31" width="504" class="common_img" src="'+e+'" style="width:500px;"><ol start="4"><li>Press the <strong>i</strong> key to enter edit mode.</li></ol><img loading="lazy" height="622" width="749" class="common_img" src="'+i+'" style="width:500px;"><ol start="5"><li>Change the master hotspot’s Wi-Fi password to <strong>123456789</strong> and then uncomment the corresponding line. As shown in the figure below:</li></ol><img loading="lazy" height="115" width="737" class="common_img" src="'+y+'" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The password must be at least 8 characters long.</strong></p></div><ol start="6"><li><p>After modifying, press <strong>Esc</strong> to exit edit mode, then save and exit by entering:</p><div class="language-py vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">py</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:wq</span></span></code></pre></div></li></ol><img loading="lazy" height="284" width="741" class="common_img" src="'+n+'" style="width:500px;"><ol start="7"><li><p>Finally, reboot the device by entering the following command. <strong>Do not skip this step.</strong></p><div class="language-py vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">py</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sudo reboot</span></span></code></pre></div></li></ol><p><strong>2. Slave Robot Configuration</strong></p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>This example demonstrates the configuration using a single slave robot. The same method can be applied to multiple slave robots.</strong></p></div><ol><li><p>Open the command line terminal and navigate to the Wi-Fi configuration directory. Enter the following command and press <strong>Enter</strong>.</p><div class="language-py vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">py</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cd hiwonder</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">toolbox</span></span></code></pre></div></li></ol><img loading="lazy" height="83" width="734" class="common_img" src="'+t+'" style="width:500px;"><ol start="2"><li><p>Open the Wi-Fi configuration file using the vi editor by entering:</p><div class="language-py vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">py</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sudo vim wifi_conf.py</span></span></code></pre></div></li></ol><img loading="lazy" height="31" width="504" class="common_img" src="'+e+'" style="width:500px;"><p>Press the <strong>i</strong> key to enter edit mode.</p><img loading="lazy" height="470" width="738" class="common_img" src="'+b+'" style="width:500px;"><ol start="3"><li>Set the hotspot name and password to match the master robot, using the default ID <strong>HW-F119CEEE</strong> in this lesson, then uncomment the corresponding lines in the code. As shown in the figure below:</li></ol><img loading="lazy" height="423" width="739" class="common_img" src="'+k+'" style="width:500px;"><ol start="4"><li><p>After modifying, press <strong>Esc</strong> to exit edit mode, then save and exit by entering:</p><div class="language-py vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">py</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:wq</span></span></code></pre></div></li></ol><img loading="lazy" height="469" width="740" class="common_img" src="'+v+'" style="width:500px;"><ol start="5"><li><p>Finally, reboot the device by entering the following command. <strong>Do not skip this step.</strong></p><div class="language-py vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">py</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sudo reboot</span></span></code></pre></div></li></ol><p><strong>3. Group Control</strong></p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>When using group control, slave robots must be powered on only after the master robot is fully operational.c</strong></p></div><ol><li><p>Place all robots on a flat, open surface, keeping a reasonable distance between each robot.</p></li><li><p>Insert the PS2 wireless controller’s receiver into the master robot’s USB port and turn it on to control the robot group.</p></li><li><p>During group control, only single commands can be sent. To perform actions such as continuously moving forward, press the controller buttons multiple times instead of holding the stick.</p></li></ol><h3 id="_15-2-4-project-outcome" tabindex="-1">15.2.4 Project Outcome <a class="header-anchor" href="#_15-2-4-project-outcome" aria-label="Permalink to &quot;15.2.4 Project Outcome&quot;">​</a></h3><p>After the program starts, the slave robots execute the same set of actions simultaneously with the master robot.</p>',90)])])}const D=a(E,[["render",f]]);export{A as __pageData,D as default};
